// The JSON policy format reader and writer. Each `tests/parity/policies-json/<name>.cedar.json` (and
// `<name>.linked.json`) has a `<name>.expected` generated by
// scripts/generate-policy-json-parity-cases.sh: whether `cedar check-parse --policy-format json`
// accepts the file and, for a `.cedar.json` file it accepts, Rust's Cedar text of the policy set.
// The Rust CLI reads the file into a `serde_json::Value` first, so the cases are read with a
// repeated key keeping its last value, and dispatched to a policy set or a single policy by their
// fields as the CLI dispatches them.

#include "json/JsonReader.hpp"
#include "json/PolicyJson.hpp"
#include "json/ValueJson.hpp"
#include "syntax/Printer.hpp"

#include <cedar/Expression.hpp>
#include <cedar/Json.hpp>
#include <cedar/Policy.hpp>
#include <cedar/PolicySet.hpp>
#include <cedar/Syntax.hpp>

#include <gtest/gtest.h>

#include <algorithm>
#include <array>
#include <expected>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <memory_resource>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace
{

auto ReadFile(const std::filesystem::path& path) -> std::string
{
    std::ifstream input{path, std::ios::binary};
    return {std::istreambuf_iterator<char>{input}, std::istreambuf_iterator<char>{}};
}

/// The policy set the Rust CLI's `read_json_policy_set` makes of `text`, or nothing when it fails.
auto ReadLikeTheCli(const std::string& text) -> std::optional<cedar::PolicySet>
{
    std::pmr::monotonic_buffer_resource scratch;
    auto document = cedar::detail::ReadJson(text, scratch);
    if (!document) { return std::nullopt; }
    const cedar::detail::JsonNode& root = document->Root();
    if (!root.IsObject()) { return std::nullopt; }
    constexpr std::array<std::string_view, 3> SetFields{"staticPolicies", "templates", "templateLinks"};
    constexpr std::array<std::string_view, 5> PolicyFields{"action", "effect", "principal", "resource", "conditions"};
    bool isSet = false;
    bool isPolicy = false;
    for (const cedar::detail::JsonMember& member : root.Members())
    {
        isSet = isSet || std::ranges::find(SetFields, member.key) != SetFields.end();
        isPolicy = isPolicy || std::ranges::find(PolicyFields, member.key) != PolicyFields.end();
    }
    if (isSet == isPolicy) { return std::nullopt; }
    if (isSet)
    {
        auto set = cedar::detail::ReadPolicySetJson(text, cedar::detail::DuplicateKeys::LastWins, "<case>");
        if (!set) { return std::nullopt; }
        return *std::move(set);
    }
    auto body = cedar::detail::ReadPolicyOrTemplateJson(text, cedar::detail::DuplicateKeys::LastWins,
                                                        cedar::PolicyId{"JSON policy"}, "<case>");
    if (!body) { return std::nullopt; }
    cedar::PolicySet set;
    if ((*body)->IsStatic()) { EXPECT_TRUE(set.Add(*cedar::Policy::Static(*body)).has_value()); }
    else { EXPECT_TRUE(set.AddTemplate(*body).has_value()); }
    return set;
}

auto Canonical(const cedar::PolicySet& set) -> std::string
{
    return cedar::detail::PrintPolicySet(set, cedar::detail::TextChoice::Canonical);
}

/// The condition of every policy and template in `set`, by id, as DumpExpression shows it: the
/// evaluated tree, folded nodes included.
auto Conditions(const cedar::PolicySet& set) -> std::vector<std::string>
{
    std::vector<std::string> conditions;
    for (const auto& policy : set.Policies())
    {
        conditions.push_back(std::string{policy->Id().Text()} + ": " +
                             cedar::DumpExpression(policy->Arena(), policy->Condition()));
    }
    for (const auto& body : set.Templates())
    {
        conditions.push_back(std::string{body->Id().Text()} + ": " +
                             cedar::DumpExpression(body->Arena(), body->Condition()));
    }
    std::ranges::sort(conditions);
    return conditions;
}

TEST(PolicyJson, AgreesWithTheReferenceCases)
{
    std::vector<std::filesystem::path> cases;
    for (const auto& entry : std::filesystem::directory_iterator{CEDAR_POLICY_JSON_PARITY_DIRECTORY})
    {
        const std::string name = entry.path().filename().string();
        if (name.ends_with(".cedar.json") || name.ends_with(".linked.json")) { cases.push_back(entry.path()); }
    }
    std::ranges::sort(cases);
    ASSERT_GE(cases.size(), 40U);
    std::size_t accepted = 0;
    for (const std::filesystem::path& path : cases)
    {
        SCOPED_TRACE(path.filename().string());
        const std::string name = path.filename().string();
        const std::size_t suffix = name.ends_with(".cedar.json") ? std::string_view{".cedar.json"}.size()
                                                                 : std::string_view{".linked.json"}.size();
        const std::string stem = name.substr(0, name.size() - suffix);
        const std::string expected = ReadFile(path.parent_path() / (stem + ".expected"));
        ASSERT_FALSE(expected.empty()) << "no expectation; run scripts/generate-policy-json-parity-cases.sh";

        const auto read = ReadLikeTheCli(ReadFile(path));
        if (expected == "reject\n")
        {
            EXPECT_FALSE(read.has_value()) << "accepted:\n" << Canonical(*read);
            continue;
        }
        ASSERT_TRUE(expected.starts_with("accept\n"));
        ASSERT_TRUE(read.has_value()) << "rejected";
        ++accepted;
        if (expected != "accept\n") { EXPECT_EQ("accept\n" + Canonical(*read) + "\n", expected); }

        // Written back out, the set reads as the same policies, unless a link uses a template
        // without slots: that template is not listed, so it is not written, and the link cannot be
        // read back (as with Rust's `PolicySet::to_json`).
        const std::string json = cedar::ToJson(*read);
        const auto again = cedar::PolicySetFromJson(json);
        const bool linksUnlistedTemplate = std::ranges::any_of(read->Policies(), [&](const auto& policy) {
            return !policy->IsStatic() && read->GetTemplate(policy->TemplateId()->Text()) == nullptr;
        });
        if (linksUnlistedTemplate)
        {
            ASSERT_FALSE(again.has_value()) << json;
            EXPECT_EQ(again.error().Primary().code, cedar::DiagnosticCode::LinkNoSuchTemplate);
            continue;
        }
        ASSERT_TRUE(again.has_value()) << json << "\n" << again.error().Render();
        EXPECT_EQ(Canonical(*again), Canonical(*read));
        EXPECT_EQ(Conditions(*again), Conditions(*read));
        EXPECT_EQ(cedar::ToJson(*again), json);
    }
    EXPECT_GE(accepted, 30U);
}

TEST(PolicyJson, CedarTextRoundTripsThroughJson)
{
    std::size_t sets = 0;
    for (const auto& entry : std::filesystem::directory_iterator{CEDAR_POLICY_PARITY_DIRECTORY})
    {
        if (entry.path().extension() != ".cedar") { continue; }
        SCOPED_TRACE(entry.path().filename().string());
        const auto parsed = cedar::ParsePolicySet(ReadFile(entry.path()));
        if (!parsed) { continue; }
        ++sets;
        const std::string json = cedar::ToJson(*parsed);
        const auto read = cedar::PolicySetFromJson(json);
        ASSERT_TRUE(read.has_value()) << json << "\n" << read.error().Render();
        // The same canonical text and the same evaluated trees, folded constructors and sets included.
        EXPECT_EQ(Canonical(*read), Canonical(*parsed));
        EXPECT_EQ(Conditions(*read), Conditions(*parsed));
    }
    EXPECT_GE(sets, 25U);
}

TEST(PolicyJson, ReadsTheSameTreeAsCedarText)
{
    const auto parsed = cedar::ParsePolicy(R"(permit(principal, action in [Action::"a"], resource)
        when { ip("10.0.0.1").isInRange(ip("10.0.0.0/8")) && [1, decimal("1.0")].contains(2) }
        unless { context.x != 3 || principal is User in [Group::"g"] };)");
    ASSERT_TRUE(parsed.has_value()) << parsed.error().Render();
    const auto read = cedar::PolicyFromJson(cedar::ToJson(*parsed));
    ASSERT_TRUE(read.has_value()) << read.error().Render();
    EXPECT_EQ(cedar::DumpExpression(read->Arena(), read->Condition()),
              cedar::DumpExpression(parsed->Arena(), parsed->Condition()));
    EXPECT_EQ(read->Id().Text(), "JSON policy");
}

TEST(PolicyJson, FoldsUnlessIntoTheCondition)
{
    const auto read = cedar::PolicyFromJson(R"({"effect": "permit", "principal": {"op": "All"},
        "action": {"op": "All"}, "resource": {"op": "All"},
        "conditions": [{"kind": "when", "body": {"Var": "context"}},
                       {"kind": "unless", "body": {"Var": "principal"}}]})",
                                            cedar::PolicyId{"p"});
    ASSERT_TRUE(read.has_value()) << read.error().Render();
    EXPECT_EQ(read->Id().Text(), "p");
    const auto condition = read->GetTemplate().NonScopeCondition();
    ASSERT_TRUE(condition.has_value());
    EXPECT_EQ(cedar::DumpExpression(read->Arena(), *condition), "(&& context (! principal))");
}

TEST(PolicyJson, PolicyAndTemplateReadersCheckForSlots)
{
    constexpr std::string_view Static =
        R"({"effect": "forbid", "principal": {"op": "All"}, "action": {"op": "All"}, "resource": {"op": "All"}, "conditions": []})";
    constexpr std::string_view WithSlot =
        R"({"effect": "forbid", "principal": {"op": "in", "slot": "?principal"}, "action": {"op": "All"}, "resource": {"op": "All"}, "conditions": []})";
    EXPECT_TRUE(cedar::PolicyFromJson(Static).has_value());
    const auto notStatic = cedar::PolicyFromJson(WithSlot);
    ASSERT_FALSE(notStatic.has_value());
    EXPECT_TRUE(notStatic.error().HasCode(cedar::DiagnosticCode::ExpectedStaticPolicy));

    const auto body = cedar::TemplateFromJson(WithSlot);
    ASSERT_TRUE(body.has_value()) << body.error().Render();
    EXPECT_EQ((*body)->Id().Text(), "JSON policy");
    const auto notTemplate = cedar::TemplateFromJson(Static);
    ASSERT_FALSE(notTemplate.has_value());
    EXPECT_TRUE(notTemplate.error().HasCode(cedar::DiagnosticCode::ExpectedTemplate));
}

TEST(PolicyJson, PolicySetReaderRefusesRepeatedKeys)
{
    // Rust's `PolicySet::from_json_str` streams the text and refuses a repeated key; the CLI, which
    // reads a `serde_json::Value` first, keeps the last value.
    const std::string text = R"({"templates": {}, "templateLinks": [], "staticPolicies": {"p": {"effect": "permit",
        "principal": {"op": "All"}, "action": {"op": "All"}, "resource": {"op": "All"}, "conditions": [],
        "conditions": []}}})";
    const auto strict = cedar::PolicySetFromJson(text);
    ASSERT_FALSE(strict.has_value());
    EXPECT_TRUE(strict.error().HasCode(cedar::DiagnosticCode::DuplicateKey)) << strict.error().Render();
    EXPECT_TRUE(cedar::detail::ReadPolicySetJson(text, cedar::detail::DuplicateKeys::LastWins, "<text>").has_value());
}

TEST(PolicyJson, DoesNotListTemplatesWithoutSlots)
{
    constexpr std::string_view Body =
        R"({"effect": "permit", "principal": {"op": "All"}, "action": {"op": "All"}, "resource": {"op": "All"}, "conditions": []})";
    const auto unlinked = cedar::PolicySetFromJson(
        std::string{R"({"templates": {"t": )"} + std::string{Body} + R"(}, "staticPolicies": {}, "templateLinks": []})");
    ASSERT_TRUE(unlinked.has_value()) << unlinked.error().Render();
    EXPECT_EQ(unlinked->TemplateCount(), 0U);

    const auto linked = cedar::PolicySetFromJson(std::string{R"({"templates": {"t": )"} + std::string{Body} +
                                                 R"(}, "staticPolicies": {}, "templateLinks": [{"templateId": "t", "newId": "l", "values": {}}]})");
    ASSERT_TRUE(linked.has_value()) << linked.error().Render();
    // Rust's `from_est` does not list it even when a link uses it; it is kept for the link.
    EXPECT_EQ(linked->TemplateCount(), 0U);
    EXPECT_EQ(linked->GetTemplate("t"), nullptr);
    EXPECT_EQ(linked->AllTemplates().size(), 1U);
    ASSERT_NE(linked->GetPolicy("l"), nullptr);
    EXPECT_FALSE(linked->GetPolicy("l")->IsStatic());
    EXPECT_EQ(linked->LinkedPolicies("t").value().size(), 1U);

    // Either way its id stays taken, and linking it again fails as in Rust's public `link`.
    for (const auto* set : {&*unlinked, &*linked})
    {
        cedar::PolicySet copy = *set;
        EXPECT_FALSE(copy.Link("t", cedar::PolicyId{"again"}, {}).has_value());
        EXPECT_EQ(copy.Link("t", cedar::PolicyId{"again"}, {}).error().Primary().code,
                  cedar::DiagnosticCode::LinkNoSuchTemplate);
        EXPECT_FALSE(copy.Add(*cedar::Policy::Static(copy.AllTemplates().front()->WithId(cedar::PolicyId{"t"}))).has_value());
        EXPECT_FALSE(copy.IsEmpty());
    }
}

TEST(PolicyJson, WritesALinkedPolicyWithItsBindings)
{
    auto set = cedar::ParsePolicySet(R"(permit(principal == ?principal, action, resource in ?resource);)");
    ASSERT_TRUE(set.has_value());
    cedar::SlotBindings bindings;
    bindings.Bind(cedar::SlotId::Principal, *cedar::EntityUid::Create("User", "alice"))
        .Bind(cedar::SlotId::Resource, *cedar::EntityUid::Create("Album", "a"));
    ASSERT_TRUE(set->Link("policy0", cedar::PolicyId{"link"}, bindings).has_value());

    const std::string policy = cedar::ToJson(*set->GetPolicy("link"));
    EXPECT_EQ(policy, R"({"effect":"permit","principal":{"op":"==","entity":{"type":"User","id":"alice"}},)"
                      R"("action":{"op":"All"},"resource":{"op":"in","entity":{"type":"Album","id":"a"}},"conditions":[]})");
    EXPECT_TRUE(cedar::PolicyFromJson(policy).has_value());

    const std::string json = cedar::ToJson(*set);
    EXPECT_NE(json.find(R"("templateLinks":[{"templateId":"policy0","newId":"link","values":{)"
                        R"("?principal":{"__entity":{"type":"User","id":"alice"}},)"
                        R"("?resource":{"__entity":{"type":"Album","id":"a"}}}}])"),
              std::string::npos)
        << json;
    const auto read = cedar::PolicySetFromJson(json);
    ASSERT_TRUE(read.has_value()) << read.error().Render();
    ASSERT_NE(read->GetPolicy("link"), nullptr);
    EXPECT_EQ(*read->GetPolicy("link")->Binding(cedar::SlotId::Resource), *cedar::EntityUid::Create("Album", "a"));
}

} // namespace
